// Lista de frases motivacionales Marathon Sports
const FRASES = [
  "El cliente vino solo 'a mirar'... pero hoy sale con calzado de alta gama, camiseta y 3 pares de medias Marathon. ¡A romperla!",
  "Nivel de energía: 100% actitud, 0% excusas. ¡Hoy Portal Carapungo lidera la tabla de ventas!",
  "Si los atletas entrenan 4 años para 10 segundos de gloria, ¡tú puedes superar tu meta de hoy en este turno!",
  "Cada '¿Tiene en talla 39?' es un pase gol frente al arco. ¡Asesora con pasión y cierra con fuerza!",
  "Hoy no se nos escapa ni un ticket. Venta cruzada activa: 'Llévese el limpiador, las medias y las canilleras de una vez'.",
  "El éxito en piso se construye cliente a cliente. Saluda con entusiasmo y transmite la grandeza de nuestra marca.",
  "Ponte las zapatillas más cómodas y la mejor sonrisa: hoy vas a superar todas tus marcas personales.",
  "Tu meta diaria no es tu techo, es tu punto de partida. ¡Ve por ese ticket doble hoy!"
];

const now = new Date();
const currentDay = now.getDate() || 24;
const randomQuote = FRASES[Math.floor(Math.random() * FRASES.length)];

const rawMetas = $input.all();
const results = [];

for (const item of rawMetas) {
  const m = item.json;
  if (!m || m.cedula === '0000000000' || m.cargo === 'TOTAL TIENDA') continue;

  const nombreCompleto = `${m.nombres || ''} ${m.apellidos || ''}`.trim();
  const primerNombre = (m.nombres || '').split(' ')[0] || 'Asesor';

  let metaDiarias = {};
  if (typeof m.metas_diarias === 'string') {
    try { metaDiarias = JSON.parse(m.metas_diarias); } catch { metaDiarias = {}; }
  } else if (m.metas_diarias) {
    metaDiarias = m.metas_diarias;
  }

  const metaHoy = metaDiarias[currentDay] ?? metaDiarias[String(currentDay)] ?? m.meta_diaria ?? 0;
  const metaMes = m.meta_mensual ?? 0;
  const metaSemanal = m.meta_semanal ?? 0;

  // Formato de Mensaje Telegram / WhatsApp
  const mensaje = `🏃‍♂️ *PORTAL MARATHON - SHOPPING CARAPUNGO (MCP1)* 🏃‍♂️\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
    `👋 ¡Hola *${primerNombre}*! (${m.cargo})\n\n` +
    `🎯 *TU META DE HOY (Día ${currentDay})*: *$${Number(metaHoy).toLocaleString('en-US', { minimumFractionDigits: 2 })}*\n` +
    `📅 *Meta Período Activo*: *$${Number(metaSemanal).toLocaleString('en-US', { minimumFractionDigits: 2 })}*\n` +
    `⭐ *Meta Mensual Agosto*: *$${Number(metaMes).toLocaleString('en-US', { minimumFractionDigits: 2 })}*\n` +
    `🛍️ *Ticket Promedio Objetivo*: *$112.82* (Conversión Tienda: 72.47%)\n\n` +
    `🔥 *ALIENTO DEL DÍA*:\n` +
    `_"${randomQuote}"_\n\n` +
    `📲 *Revisa tu avance y turnos en vivo en el Portal:*\n` +
    `http://localhost:5174/metas\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━━━━━`;

  results.push({
    json: {
      cedula: m.cedula,
      nombre: nombreCompleto,
      primerNombre,
      cargo: m.cargo,
      metaHoy,
      metaSemanal,
      metaMes,
      mensaje,
      randomQuote
    }
  });
}

return results;
